const KEY="cravedish_stitch_v2";
const state=JSON.parse(localStorage.getItem(KEY)||'{"cart":[],"orders":[],"addresses":[{"id":"home","label":"Home","text":"Flat 402, Sai Residency, Velachery, Chennai","phone":"+91 98765 43210","default":true},{"id":"hostel","label":"Hostel","text":"Sai University Hostel, Paiyanur, Chennai","phone":"+91 91234 56789","default":false}],"selectedAddress":"home","favorites":[],"restaurant":0}');
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
function toast(msg){const t=document.getElementById('toast');if(!t)return;t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function money(n){return "₹"+Number(n).toLocaleString("en-IN")}
function go(page, params=""){location.href=page+params}
function setNav(){document.querySelectorAll(".nav a").forEach(a=>a.classList.toggle("active",a.dataset.page===document.body.dataset.page))}
function restaurantData(){return RESTAURANTS||[]}
function dishFor(r,i){return DISHES[r%DISHES.length][i%15]}
function addDishByIndex(i){addToCart(state.restaurant,DISHES[state.restaurant%DISHES.length][i])}
function addToCart(r,d){if(state.cart.length&&state.cart.some(x=>x.r!==r)){if(!confirm("Your cart has items from another restaurant. Clear it and add this item?"))return;state.cart=[]}const item=state.cart.find(x=>x.r===r&&x.d===d.name);if(item)item.qty++;else state.cart.push({r,d:d.name,price:d.price,qty:1,img:d.img});save();renderOrderBox();toast(d.name+" added to your order")}
function changeQty(i,delta){state.cart[i].qty+=delta;if(state.cart[i].qty<=0)state.cart.splice(i,1);save();renderOrderBox();renderProfileCart()}
function renderOrderBox(){const box=document.getElementById("orderItems");if(!box)return;const total=state.cart.reduce((s,x)=>s+x.price*x.qty,0);box.innerHTML=state.cart.length?state.cart.map((x,i)=>`<div class="order-item"><span>${x.d}<br><small>${money(x.price)}</small></span><span class="qty"><button onclick="changeQty(${i},-1)">−</button>${x.qty}<button onclick="changeQty(${i},1)">+</button></span></div>`).join(""):`<div style="padding:25px 5px;color:#8f6f6e;text-align:center">Your order is empty.<br>Add dishes to start.</div>`;const el=document.getElementById("itemTotal");if(el)el.textContent=money(total);const fee=total?total>=499?0:40:0;document.getElementById("deliveryFee")&&(document.getElementById("deliveryFee").textContent=fee?money(fee):"FREE");document.getElementById("grandTotal")&&(document.getElementById("grandTotal").textContent=money(total+fee))}
function placeOrder(){if(!state.cart.length)return toast("Add at least one dish");const total=state.cart.reduce((s,x)=>s+x.price*x.qty,0);const fee=total>=499?0:40;const order={id:"CD-"+Math.floor(100000+Math.random()*899999),date:new Date().toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"}),restaurant:restaurantData()[state.restaurant]?.name||"CraveDish Restaurant",items:state.cart.map(x=>({...x})),total:total+fee,address:state.addresses.find(a=>a.id===state.selectedAddress)||state.addresses[0],status:"Placed"};state.orders.unshift(order);state.cart=[];save();renderOrderBox();toast("Order placed successfully");setTimeout(()=>go("profile.html"),500)}
function cancelOrder(id){const o=state.orders.find(x=>x.id===id);if(!o)return;o.status="Cancelled";save();renderProfile();toast("Order cancelled")}
function addAddress(){document.getElementById("addressModal").classList.add("show")}
function closeModal(){document.querySelectorAll(".modal").forEach(x=>x.classList.remove("show"))}
function saveAddress(e){e.preventDefault();const f=new FormData(e.target);const a={id:"a"+Date.now(),label:f.get("label"),text:f.get("address"),phone:f.get("phone"),default:false};state.addresses.forEach(x=>x.default=false);state.addresses.push(a);state.selectedAddress=a.id;save();closeModal();renderAddresses();toast("Delivery address updated")}
function selectAddress(id){state.selectedAddress=id;state.addresses.forEach(a=>a.default=a.id===id);save();renderAddresses();toast("Delivery address changed")}
function renderAddresses(){const el=document.getElementById("addresses");const top=document.getElementById("topAddress");const selected=state.addresses.find(a=>a.id===state.selectedAddress)||state.addresses[0];if(top&&selected)top.textContent=selected.text.split(",")[0];if(!el)return;el.innerHTML=state.addresses.map(a=>`<div class="address"><strong>⌂ ${a.label} ${a.default?'<span class="pill red" style="float:right;font-size:8px">Default</span>':''}</strong><div>${a.text}</div><div>Phone: ${a.phone}</div><br><button onclick="selectAddress('${a.id}')">${a.default?'Selected':'Make default'}</button></div>`).join("")}
function renderProfile(){const el=document.getElementById("ordersList");if(!el)return;el.innerHTML=state.orders.length?state.orders.map(o=>`<div class="order-card"><div class="order-card-head"><div><b>${o.restaurant}</b><div style="font-size:10px;color:#8f6f6e">${o.date} • ${o.id}</div></div><b class="${o.status==='Cancelled'?'':'status'}">${o.status}</b></div><div style="background:#f6f3f2;padding:9px;border-radius:7px;margin:10px 0;font-size:11px">${o.items.map(i=>`${i.qty}× ${i.d}`).join("<br>")}</div><div style="display:flex;justify-content:space-between;align-items:center"><b>${money(o.total)}</b>${o.status==="Placed"?`<button class="secondary-btn" onclick="cancelOrder('${o.id}')">Cancel Order</button>`:`<button class="secondary-btn" onclick="go('restaurants.html')">Order Again</button>`}</div></div>`).join(""):`<div style="text-align:center;padding:50px;color:#8f6f6e">No orders yet. Browse restaurants and place your first order.</div>`;renderAddresses()}
function renderProfileCart(){/* profile page doesn't need live cart, retained for shared actions */}
function initHome(){setNav();const grid=document.getElementById("homeRestaurants");if(!grid)return;const featured=["Chennai Tiffin House","A2B - Adyar Ananda Bhavan","Barbeque Nation","Cream Centre","Writer's Cafe","The Farm"];const list=featured.map(n=>restaurantData().find(r=>r.name===n)).filter(Boolean);grid.innerHTML=list.map(r=>cardHTML(r,restaurantData().indexOf(r))).join("")}
function cardHTML(r,i){return `<article class="restaurant-card" onclick="state.restaurant=${i};save();go('restaurant.html')"><div class="card-img"><img src="${r.img}" alt="${r.name}" loading="lazy" onerror="this.onerror=null;this.src='data:image/jpeg;base64,'"><span class="badge">${i%3===0?'20% OFF':i%3===1?'FAST DELIVERY':'PURE VEG'}</span><button class="heart" onclick="event.stopPropagation();toast('Saved to favourites')">♡</button></div><div class="card-body"><div class="card-title"><h3>${r.name}</h3><span class="rating">${r.rating} ★</span></div><p>${r.cuisine} • ${r.area}</p><p>${money(r.cost)} for two • ${r.distance} km</p><div class="meta"><span>◷ ${r.eta} mins</span><span class="good">${r.note}</span></div></div></article>`}
function initRestaurants(){setNav();const grid=document.getElementById("restaurantGrid");if(!grid)return;let list=restaurantData();const q=(document.getElementById("restaurantSearch")?.value||"").toLowerCase();if(q)list=list.filter(r=>(r.name+r.cuisine+r.area).toLowerCase().includes(q));const cuisine=document.getElementById("cuisineFilter")?.value;if(cuisine&&cuisine!=="All")list=list.filter(r=>r.cuisine.includes(cuisine));grid.innerHTML=list.map((r,i)=>cardHTML(r,restaurantData().indexOf(r))).join("");document.getElementById("restaurantCount").textContent=list.length+" restaurants"}
function initRestaurant(){setNav();const r=restaurantData()[state.restaurant]||restaurantData()[0];document.querySelectorAll("[data-r-name]").forEach(x=>x.textContent=r.name);document.querySelectorAll("[data-r-area]").forEach(x=>x.textContent=r.area);const g=document.getElementById("gallery");if(g)g.innerHTML=(()=>{const L=[...new Set(restaurantData().map(x=>x.img).filter(u=>u.startsWith("data:")))];const k=Math.max(0,L.indexOf(r.img));return [r.img,L[(k+3)%L.length],L[(k+6)%L.length]]})().map((u,i)=>`<img src="${u}" alt="${r.name} food ${i+1}">`).join("");const list=document.getElementById("dishList");if(list)list.innerHTML=DISHES[state.restaurant%DISHES.length].map((d,di)=>`<div class="dish"><div class="dish-info"><span class="pill ${d.veg?'green':'red'}">${d.veg?'● Veg':'● Non-Veg'}</span><h3>${d.name}</h3><b>${money(d.price)}</b><p>${d.desc}</p><div class="dish-bottom"><small style="color:#006e26">★ ${d.rating} • ${d.reviews} ratings</small><button class="add" onclick="addDishByIndex(${di})">ADD +</button></div></div><img class="dish-img" src="${d.img}" alt="${d.name}"></div>`).join("");renderOrderBox()}
function bindGlobal(){setNav();document.querySelectorAll("[data-location]").forEach(x=>x.addEventListener("click",addAddress))}
document.addEventListener("DOMContentLoaded",()=>{bindGlobal();initHome();initRestaurants();initRestaurant();renderProfile();renderAddresses();renderOrderBox()});
